# Generated by Manimator. Render with:  manim -pqm scene.py First

from manim import *


class First(Scene):
    def construct(self):
        # Objects
        dot = Dot(radius=0.1)
        dot.set_stroke(WHITE)
        dot.set_fill(WHITE)
        dot.move_to([1, 1, 0])

        # Animation
        self.play(Create(dot), run_time=1)


class Second(MovingCameraScene):
    def construct(self):
        # Objects
        square = Square(side_length=2)
        square.set_stroke(BLUE)
        square.set_fill(BLUE)
        square.move_to([-1, 0, 0])

        self.add(square)

        # Animation
        self.play(
            self.camera.frame.animate.move_to(square).set(width=config.frame_width / 2),
            run_time=1,
        )
